#include <stdio.h>
#include <limits.h>

int will_overflow(int x)
{
    return x + 1 < x;        /* UB when x == INT_MAX; may be folded to 0 */
}

int main(void)
{
    printf("%d\n", will_overflow(INT_MAX));
    return 0;
}

#include <stdio.h>

int main(void)
{
    int values[4] = {1, 2, 3, 4};
    int sum = 0;

    for (int i = 0; i <= 4; i++) {      /* <= reads values[4] */
        sum += values[i];
    }
    printf("sum = %d\n", sum);
    return 0;
}

#include <stdio.h>

int main(void)
{
    char *literal = "hello";     /* points into read-only memory */
    char array[] = "hello";      /* a writable copy */

    array[0] = 'H';
    printf("%s\n", array);

    literal[0] = 'H';            /* undefined behaviour */
    printf("%s\n", literal);
    return 0;
}

#include <assert.h>
#include <stdio.h>

double average(const int *values, size_t n)
{
    assert(n > 0 && "average of an empty array");
    int total = 0;
    for (size_t i = 0; i < n; i++) total += values[i];
    return (double)total / n;
}

int main(void)
{
    int data[] = {4, 8};
    printf("%.1f\n", average(data, 2));
    printf("%.1f\n", average(data, 0));
    return 0;
}
